find:
// A bare `$ref` first: where both spellings are present the direct one is
// the node's own claim, and `allOf` beside it would be the composition case
// that throws anyway.
const ref = typeof current['$ref'] === 'string' ? current['$ref'] : soleAllOfRef(current);

replace:
// The alias wrapper first, falling back to the bare `$ref`. Equivalent on
// every node either committed document contains — no node carries both
// spellings — and it differs only on one that does, which is why this is a
// control rather than a defect.
const ref = soleAllOfRef(current) ?? (typeof current['$ref'] === 'string' ? current['$ref'] : null);
